#!/usr/bin/env python3
"""Generate deterministic ground truth for CSX-325_Q1."""

from __future__ import annotations

import json
import re
from html.parser import HTMLParser
from pathlib import Path
from typing import Any


TASK_ID = "CSX-325_Q1"
EVENT_ID = "CSX-325"
TASK_DIR = Path(__file__).resolve().parent
REPO_ROOT = Path(__file__).resolve().parents[3]
PACKAGE = REPO_ROOT / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID
OUT = TASK_DIR / "computed_gt.json"


class TextExtractor(HTMLParser):
    def __init__(self) -> None:
        super().__init__()
        self.parts: list[str] = []
        self.skip_depth = 0

    def handle_starttag(self, tag: str, attrs: list[tuple[str, str | None]]) -> None:
        if tag.lower() in {"script", "style", "noscript"}:
            self.skip_depth += 1

    def handle_endtag(self, tag: str) -> None:
        if tag.lower() in {"script", "style", "noscript"} and self.skip_depth:
            self.skip_depth -= 1

    def handle_data(self, data: str) -> None:
        if not self.skip_depth and data.strip():
            self.parts.append(data.strip())

    def text(self) -> str:
        return re.sub(r"\s+", " ", " ".join(self.parts)).strip()


def clean_ascii(text: str) -> str:
    replacements = {
        "\u00a0": " ",
        "\u2018": "'",
        "\u2019": "'",
        "\u201c": '"',
        "\u201d": '"',
        "\u2013": "-",
        "\u2014": "-",
    }
    for old, new in replacements.items():
        text = text.replace(old, new)
    return re.sub(r"\s+", " ", text.encode("ascii", errors="ignore").decode("ascii")).strip()


def read_json(rel_path: str) -> Any:
    with (PACKAGE / rel_path).open("r", encoding="utf-8") as handle:
        return json.load(handle)


def read_html_text(rel_path: str) -> str:
    parser = TextExtractor()
    parser.feed((PACKAGE / rel_path).read_text(encoding="utf-8", errors="ignore"))
    return clean_ascii(parser.text())


def extract_float(text: str, pattern: str) -> float:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return float(match.group(1))


def extract_int(text: str, pattern: str) -> int:
    match = re.search(pattern, text, flags=re.IGNORECASE)
    if not match:
        raise ValueError(f"Pattern not found: {pattern}")
    return int(match.group(1))


def count_named_basins(text: str) -> int:
    basin_names = ("Atlantic", "Pacific", "Indian")
    return sum(1 for name in basin_names if re.search(rf"\b{name}\b", text, flags=re.IGNORECASE))


def extract_source_window(text: str) -> str:
    match = re.search(
        r"From\s+([0-9]{1,2}\s+[A-Za-z]+\s+[0-9]{4})\s+to\s+([0-9]{1,2}\s+[A-Za-z]+\s+[0-9]{4})",
        text,
        flags=re.IGNORECASE,
    )
    if not match:
        raise ValueError("NOAA status-window text not found.")
    return f"{match.group(1)} to {match.group(2)}"


def build_ground_truth() -> dict[str, Any]:
    event = read_json("metadata/event.json")
    crw_text = read_html_text("data/event_reports/event_reports_003_NOAA_Coral_Reef_Watch_bleaching_status.html")
    noaa_text = read_html_text("data/event_reports/event_reports_002_NOAA_NESDIS_fourth_global_coral_bleaching_event.html")

    current_pct = extract_float(crw_text, r"~([0-9.]+)% of the world's coral reef area")
    previous_pct = extract_float(crw_text, r"when ([0-9.]+)% of the world's reef area experienced")
    countries = extract_int(crw_text, r"at least ([0-9]+) countries and territories")
    basin_count = count_named_basins(noaa_text)
    source_window = extract_source_window(crw_text)

    increase_pp = round(current_pct - previous_pct, 1)
    relative_increase_pct = round(100 * increase_pp / previous_pct, 1)
    tests = {
        "current_pct_gte_80": current_pct >= 80,
        "increase_pp_gte_15": increase_pp >= 15,
        "relative_increase_pct_gte_20": relative_increase_pct >= 20,
        "countries_or_territories_gte_80": countries >= 80,
        "basin_count_gte_3": basin_count >= 3,
    }
    passed_tests = sum(1 for passed in tests.values() if passed)
    conclusion = "heat_stress_escalation_pass" if passed_tests == len(tests) else "heat_stress_escalation_fail"

    primary_gt = {
        "current_pct": current_pct,
        "previous_pct": previous_pct,
        "increase_pp": increase_pp,
        "relative_increase_pct": relative_increase_pct,
        "countries_or_territories": countries,
        "basin_count": basin_count,
        "passed_tests": passed_tests,
        "conclusion": conclusion,
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "target_family": "coral_bleaching_heat_stress_extent_escalation_test",
        "event": {
            "package_id": EVENT_ID,
            "event_name": event["event_name"],
            "hazard_family": event["hazard_family"],
            "event_date_or_window": source_window,
            "metadata_event_name": event["event_name"],
            "region": event["region"],
        },
        "primary_gt": primary_gt,
        "anchors": {
            "formulas": {
                "increase_pp": "current_pct - previous_pct",
                "relative_increase_pct": "100 * increase_pp / previous_pct",
                "passed_tests": "count of five threshold inequalities that evaluate true",
            },
            "thresholds": {
                "current_pct_min": 80,
                "increase_pp_min": 15,
                "relative_increase_pct_min": 20,
                "countries_or_territories_min": 80,
                "basin_count_min": 3,
            },
            "threshold_results": tests,
            "named_basins": ["Atlantic", "Pacific", "Indian"],
            "source_window": source_window,
            "rounding": "Round percentage outputs to one decimal place; relative_increase_pct uses the displayed one-decimal increase_pp.",
            "conclusion_rule": "heat_stress_escalation_pass only when passed_tests equals 5",
        },
        "tolerances": {
            "current_pct": 0.05,
            "previous_pct": 0.05,
            "increase_pp": 0.05,
            "relative_increase_pct": 0.05,
            "countries_or_territories": 0,
            "basin_count": 0,
            "passed_tests": 0,
        },
        "rubric": {
            "total_points": 20,
            "criteria": [
                {
                    "name": "JSON answer shape",
                    "points": 3,
                    "description": "Returns valid compact JSON with exactly the requested eight keys and no extra narrative.",
                },
                {
                    "name": "Package anchor extraction",
                    "points": 5,
                    "description": "Extracts 84.4%, 68.2%, 83 countries or territories, and three named basins correctly.",
                },
                {
                    "name": "Derived calculations",
                    "points": 4,
                    "description": "Computes the 16.2 percentage-point increase and 23.8% relative increase with the stated formulas.",
                },
                {
                    "name": "Threshold logic",
                    "points": 4,
                    "description": "Evaluates all five inequalities correctly and reports passed_tests as 5.",
                },
                {
                    "name": "Conclusion",
                    "points": 2,
                    "description": "Uses heat_stress_escalation_pass and rejects the marginal repeat-baseline rule from the computed thresholds.",
                },
                {
                    "name": "Concise consequence",
                    "points": 1,
                    "description": "Keeps the physical consequence to accumulated marine heat-stress extent as the supported diagnostic signal.",
                },
                {
                    "name": "No overclaim",
                    "points": 1,
                    "description": "Does not infer measured local mortality, tourism loss, or terrestrial weather causation from these metrics.",
                },
            ],
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_files": [
                "metadata/event.json",
                "data/event_reports/event_reports_003_NOAA_Coral_Reef_Watch_bleaching_status.html",
                "data/event_reports/event_reports_002_NOAA_NESDIS_fourth_global_coral_bleaching_event.html",
            ],
        },
    }


def main() -> None:
    OUT.write_text(json.dumps(build_ground_truth(), ensure_ascii=True, indent=2) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
